import { useMemo, useState } from "react";

export type Command = {
  id: string;
  label: string;
  scope: string;
  hint?: string;
};

const COMMANDS: Command[] = [
  { id: "vault.sync", label: "Sync Remote Vault", scope: "vault", hint: "Ctrl+Shift+S" },
  { id: "vault.verify", label: "Verify Asset Checksums", scope: "vault" },
  { id: "pkg.install", label: "Install Package", scope: "packages" },
  { id: "pkg.prune", label: "Prune Unused Dependencies", scope: "packages" },
  { id: "style.apply", label: "Apply Style Preset", scope: "appearance" },
];

export function CommandWorkspace() {
  const [query, setQuery] = useState("");
  const [scope, setScope] = useState("all");
  const [activeId, setActiveId] = useState<string | null>(null);

  const scopes = useMemo(
    () => ["all", ...Array.from(new Set(COMMANDS.map((c) => c.scope)))],
    [],
  );

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    return COMMANDS.filter((c) => {
      const inScope = scope === "all" || c.scope === scope;
      const hit = !q || c.label.toLowerCase().includes(q) || c.id.includes(q);
      return inScope && hit;
    });
  }, [query, scope]);

  const active = results.find((c) => c.id === activeId) ?? results[0] ?? null;

  return (
    <div className="cw-root">
      <nav className="cw-rail" aria-label="Command scopes">
        {scopes.map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => setScope(s)}
            className={s === scope ? "cw-rail-item is-active" : "cw-rail-item"}
          >
            {s}
          </button>
        ))}
      </nav>

      <section className="cw-list">
        <input
          className="cw-search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Filter commands…"
          aria-label="Filter commands"
        />
        <ul className="cw-items">
          {results.map((c) => (
            <li key={c.id}>
              <button
                type="button"
                onClick={() => setActiveId(c.id)}
                className={c.id === active?.id ? "cw-item is-active" : "cw-item"}
              >
                <span>{c.label}</span>
                {c.hint ? <kbd>{c.hint}</kbd> : null}
              </button>
            </li>
          ))}
        </ul>
      </section>

      <aside className="cw-preview" aria-live="polite">
        {active ? (
          <>
            <h3>{active.label}</h3>
            <code className="cw-id">{active.id}</code>
            <p>Scope: {active.scope}</p>
          </>
        ) : (
          <p>No matching command</p>
        )}
      </aside>
    </div>
  );
}

