.cw-root {
  display: grid;
  grid-template-columns: 176px 320px 1fr;
  height: 100%;
  min-height: 420px;
  background: var(--surface-inset, #09090b);
  color: var(--text-strong, #e4e4e7);
}
.cw-rail {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 12px 8px;
  border-right: 1px solid var(--line-subtle, #27272a);
}
.cw-rail-item {
  text-align: left;
  padding: 6px 10px;
  font-size: 12px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--text-muted, #a1a1aa);
  cursor: pointer;
}
.cw-rail-item.is-active {
  background: var(--surface-raised, #18181b);
  color: var(--text-strong, #fafafa);
}
.cw-list {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--line-subtle, #27272a);
  overflow: hidden;
}
.cw-search {
  margin: 12px;
  padding: 8px 10px;
  font-size: 13px;
  border-radius: 6px;
  border: 1px solid var(--line-strong, #3f3f46);
  background: var(--surface-raised, #18181b);
  color: inherit;
  outline: none;
}
.cw-items {
  list-style: none;
  margin: 0;
  padding: 0 8px 12px;
  overflow-y: auto;
  flex: 1;
}
.cw-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 8px 10px;
  font-size: 13px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.cw-item.is-active {
  background: var(--accent-soft, rgba(99, 102, 241, 0.16));
}
.cw-item kbd {
  font-family: ui-monospace, monospace;
  font-size: 10px;
  padding: 2px 5px;
  border-radius: 4px;
  background: var(--surface-raised, #18181b);
  border: 1px solid var(--line-subtle, #27272a);
}
.cw-preview {
  padding: 24px;
  overflow-y: auto;
}
.cw-id {
  display: inline-block;
  font-family: ui-monospace, monospace;
  font-size: 12px;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--surface-raised, #18181b);
}
